-- Relative expiry dates. Adrenaline expires in 40 days on purpose so the inventory shows an
-- "expires soon" warning in the demo; change '+40 days' if that is not wanted.
-- Ibuprofen: not recommended with asthma (demo case with C004: v_medication_warnings flags it).
INSERT INTO medications (name, form, unit, stock, min_stock, avoid_with, expires_at) VALUES
  ('Paracetamol 500 mg', 'tablet',    'tablet', 40, 10, '[]',                  strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, 'start of day', '+19 months')),
  ('Ibuprofen 400 mg',   'tablet',    'tablet', 30, 10, '["asthma"]',          strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, 'start of day', '+16 months')),
  ('Ondansetron 4 mg',   'tablet',    'tablet', 12,  4, '["qt_prolongation"]', strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, 'start of day', '+14 months')),
  ('Salbutamol',         'inhaler',   'puff',  200, 50, '[]',                  strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, 'start of day', '+22 months')),
  ('Adrenaline 0.3 mg',  'injection', 'unit',    2,  1, '[]',                  strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, 'start of day', '+40 days'));

-- Example prescription: a 3-day ibuprofen course for C001 (rescue salbutamol is on demand, no schedule).
INSERT INTO prescriptions (crew_id, medication_id, dose, every_h, start_at, end_at, active, reason, prescribed_by) VALUES
  ('C001', (SELECT id FROM medications WHERE name = 'Ibuprofen 400 mg'), 1, 8,
   strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, '-1 days'),
   strftime('%Y-%m-%dT%H:%M:%SZ', {{NOW}}, '+2 days'), 1, 'Back pain from microgravity', 'copilot');

-- Protocols. Node types: question (yes/no), action (next), end. The first array entry is the start.
INSERT INTO emergency_protocols (code, title, category, steps) VALUES
  ('radiation-shelter', 'Shelter during a solar particle event', 'radiation',
   '[{"id":1,"type":"question","text":"Is the >10 MeV proton flux above 10 pfu?","yes":2,"no":7},
     {"id":2,"type":"action","text":"Go to the shielded shelter and record the time","next":3},
     {"id":3,"type":"question","text":"Nausea or vomiting?","yes":4,"no":5},
     {"id":4,"type":"action","text":"Check the drug warnings and give ondansetron 4 mg","next":6},
     {"id":5,"type":"action","text":"Stay in the shelter and reassess symptoms every 15 minutes","next":6},
     {"id":6,"type":"end","text":"Log the event in the diary and notify the ground"},
     {"id":7,"type":"end","text":"No immediate risk: keep monitoring"}]'),
  ('chest-pain', 'Chest pain', 'cardio',
   '[{"id":1,"type":"question","text":"Pressing pain lasting more than 5 minutes?","yes":2,"no":4},
     {"id":2,"type":"action","text":"Take an ECG and SpO2; prepare a priority contact with the ground","next":3},
     {"id":3,"type":"end","text":"Rest and monitor continuously until the ground replies"},
     {"id":4,"type":"action","text":"Reassess in 15 minutes","next":5},
     {"id":5,"type":"end","text":"If the pain returns, repeat this protocol; log the episode in the diary"}]');
